namespace Tsumo.Cli
{
    public class IndexedSourceText
    {
        public Tsonic.CSharp.Js.JSArray<string> characters;
        public Tsonic.CSharp.Js.JSArray<int> utf16Offsets;
        public int length;
        public IndexedSourceText(string source)
        {
            this.characters = Tsonic.CSharp.Js.JSArrayStatics.from(source);
            this.utf16Offsets = new Tsonic.CSharp.Js.JSArray<int>(new int[] { 0 });
            int utf16Offset = 0;
            for (int index = 0; index < this.characters.length; index++)
            {
                utf16Offset += this.characters[index].Length;
                this.utf16Offsets.push(utf16Offset);
            }
            this.length = this.characters.length;
        }
        public string characterAt(int index)
        {
            if (index < 0 || index >= this.length)
            {
                return "";
            }
            return this.characters[index];
        }
        public string slice(int start, int end)
        {
            return Tsonic.CSharp.Js.Array.join(Tsonic.CSharp.Js.Array.slice(this.characters, start, end), "");
        }
        public int utf16OffsetAt(int index)
        {
            return this.utf16Offsets[index];
        }
    }
}
